    skArc(profile, "arc1", { "start" : vector(10, 20) * millimeter, "mid" : vector(7.071068, 27.071068) * millimeter, "end" : vector(0, 30) * millimeter });
    skLineSegment(profile, "line3", { "start" : vector(0, 30) * millimeter, "end" : vector(0, 0) * millimeter });
