    const axis1 = newSketchOnPlane(context, id + "axis1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 1, 0), vector(0, 0, 1)) });
    skLineSegment(axis1, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(30, 0) * millimeter });
